  "Classement Lichess moyen des deux joueurs": "Durchschnittliche Bewertung Lichess beider Spieler",
  "· filtres actifs": "· Filter aktiv",
  "· toutes les parties": "· alle Schachspiele",
  "Elo minimum · chaque joueur": "Mindestens Elo · pro Spieler",
  "Elo maximum · chaque joueur": "Maximal Elo · pro Spieler",
  "Sans minimum": "Es gibt kein Minimum.",
  "Cadences du PGN": "Zeitkontrollen PGN",
  "Sans maximum": "Keine Höchstmenge",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "Keine Auswahl = alle Zeitkontrollen, einschließlich Unbekannter.",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo kommt vom PGN und muss für beide Spieler im Bereich liegen. Schachspiele ohne Elo sind ausgeschlossen, wenn eine Grenze gesetzt wird. Fehlende oder nicht anerkannte PGN-Zeitkontrollen sind \"Unbekannt\". Diese Schachspiele sind ausgeschlossen, wenn Zeitkontrollen ausgewählt werden, es sei denn, \"Unbekannt\" ist ausgewählt.",
  ": indique un nombre valide pour la borne Elo.": ": eine gültige Nummer für die Grenze Elo eingeben.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": eine ganze Zahl Elo von 0 bis 4000 eingeben oder die gebundene Stelle leer lassen.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": Das Mindestbetrag Elo darf das Maximum Elo nicht überschreiten.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "Erstellen Sie eine Datenbank und importieren Sie PGN Schachspiele in die Bibliothek.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess Master hat keine Elo oder Zeitkontrollfilter. Um eine Hauptkollektion zu filtern, wählen Sie eine importierte Datenbank wie Mega Database aus.",
  "Source principale": "Hauptquelle",
  "Mes bases PGN": "Meine Datenbanken PGN",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "Nur gespielte Mainline-Schach-Bewegungen werden gezählt. Die Analysevariationen lassen die Statistiken nicht aufblasen.",
  "Référence dans chaque ligne": "Referenz in jeder Zeile",
  "Comparer avec": "Vergleichen",
  "Mes bases de référence": "Meine Referenzdatenbanken",
  "Aucune référence": "Keine Bezugnahme",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "Diese Filter sind unabhängig von der Hauptdatenbank. Der Prozentsatz zeigt die Frequenz der Schachbewegung in dieser Position in der gewählten Referenz.",
  "Probabilité de rencontre": "Wahrscheinlichkeit der Begegnung",
  "Afficher la probabilité de la ligne": "Zeigen Sie die Wahrscheinlichkeit der Linie",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "Wählen Sie Ihre Seite direkt im Explorer. Nur die Antworten des Gegners zählen; Ihre Schachbewegungen werden angenommen. Diese Schätzung folgt der angezeigten Variation und den ausgewählten Datenbankfiltern. Bei einem PGN aus einem Diagramm hängt es von dieser Ausgangsposition ab.",
  "Mode d’analyse": "Analysemodus",
  "Rapide (~250 ms par coup)": "Schnell (~ 250 ms pro Schachbewegung)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "Eine höhere Tiefe verfeinert die Analyse und dauert länger. Von 8 bis 30, mit einer Grenze von 10 Sekunden pro Schachzug. Wenn das Ziel nicht erreicht wird, markiert ≈ das Ergebnis; schweben Sie, um seine tatsächliche Tiefe zu sehen.",
