  "Le bilan a changé. Réessaie pour l’actualiser.": "Der Bericht hat sich geändert. Versuchen Sie es noch einmal aufzufrischen.",
  "Exploration partielle : aucune lacune trouvée pour le moment.": "Teilweise Erforschung: Noch keine Lücken gefunden.",
  "Aucune lacune trouvée avec les réglages actuels.": "Keine Lücken bei den aktuellen Einstellungen gefunden.",
