  "La partie ou le répertoire a changé. La compatibilité a été vérifiée à nouveau ; choisis à nouveau Ajouter jusqu’ici si la suite convient.": "Das Schachspiel oder das Eröffnungsrepertoire änderte sich. Die Kompatibilität wurde erneut überprüft; wählen Sie hier erneut hinzufügen, wenn die Zeile geeignet ist.",
