  "avec estimation": "mit Schätzung",
  "Exploration terminée pour le seuil et la profondeur choisis.": "Die Exploration ist für die gewählte Schwelle und Tiefe abgeschlossen.",
  "Exploration partielle : les résultats peuvent encore évoluer.": "Teilweise Erforschung: Die Ergebnisse können sich noch ändern.",
  "sans estimation exploitable.": "ohne nützliche Schätzung.",
  "Plusieurs positions de départ sont examinées": "Mehrere Ausgangspositionen werden untersucht.",
  ", dont des diagrammes": ", einschließlich Diagrammen",
  ". Chaque probabilité suppose son départ déjà atteint ; elles ne s’additionnent pas entre ces départs.": ". Jede Wahrscheinlichkeit setzt voraus, dass ihre Startposition erreicht wurde; Wahrscheinlichkeiten können nicht über Startpositionen hinweg hinzugefügt werden.",
  "Ce répertoire commence sur un diagramme : les probabilités supposent cette position déjà atteinte.": "Dieses Eröffnungsrepertoire beginnt mit einem Diagramm: Die Wahrscheinlichkeiten gehen davon aus, dass diese Position bereits erreicht wurde.",
  "Aucune lacune trouvée dans les chemins examinés avec ces réglages.": "Es wurden keine Lücken in den mit diesen Einstellungen untersuchten Pfaden gefunden.",
  "La limite de cette exploration est atteinte. Affine les réglages pour réduire le nombre de positions à examiner.": "Die Explorationsgrenze wurde erreicht. Verfeinern Sie die Einstellungen, um die Anzahl der zu untersuchenden Positionen zu reduzieren.",
  "Aucune lacune trouvée pour le moment. Poursuis l’exploration pour compléter le bilan.": "Noch keine Lücken gefunden. Fortsetzen Sie die Erforschung, um den Bericht abzuschließen.",
  "Les données disponibles ne permettent pas encore de compléter le bilan. Ajuste les filtres ou réessaie plus tard.": "Die verfügbaren Daten können den Bericht noch nicht abschließen. Passen Sie die Filter an oder versuchen Sie später erneut.",
