  "Cette base sert de référence à l’explorer et à la recherche de positions. Pour travailler une partie ou la réviser, ouvre-la dans l’analyse et sauvegarde une copie dans une base personnelle.": "Diese Datenbank ist eine Referenz für die Explorator- und Positionssuche. Um ein Schachspiel zu studieren oder zu überprüfen, öffnen Sie es in der Analyse und speichern Sie eine Kopie in eine persönliche Datenbank.",
