  "Fichier importé sur la machine hébergeant Chess Gym.": "Datei auf dem Computer, auf dem Chess Gym gehostet wird.",
  "La sauvegarde complète inclut les parties de référence importées. Conserve aussi le fichier source pour pouvoir poursuivre une importation.": "Die vollständige Sicherung umfasst importierte Referenzschachspiele. Bewahren Sie auch die Quelldatei, um einen Import wieder aufzunehmen.",
