  "La partie a été supprimée de la base. Son analyse ouverte est conservée comme copie libre.": "Das Schachspiel wurde aus der Datenbank gelöscht. Seine offene Analyse ist als kostenlose Kopie erhalten.",
  "Les informations PGN sont enregistrées. Rouvre la partie pour actualiser les temps des coups. ": "PGN Informationen werden gespeichert. Öffnen Sie das Schachspiel, um die Schachbewegungszeiten zu aktualisieren. ",
