  "La fréquence utilise la dernière exploration « À compléter » de ce répertoire. Les reprises et les anciens retards restent prioritaires. Sans statistiques, l’ordre habituel est conservé.": "Frequency verwendet den neuesten \"Coverage Gaps\"-Scan dieses Eröffnungsrepertoires. Wiedererlernen und ältere überfällige Karten bleiben Priorität. Ohne Statistiken bleibt die übliche Reihenfolge.",
