  "Par base": "Nach Datenbank",
  "Les échéances et les cartes concernent les bases dont les révisions sont activées. L’activité conserve les réponses des cartes retirées et des bases désactivées encore présentes. Les bases supprimées ne sont pas incluses.": "Fälligkeitsdaten und Karten decken Datenbanken ab, bei denen Überprüfungen ermöglicht werden. Die Aktivität speichert Antworten aus entfernten Karten und stillgelegten Datenbanken, die noch existieren. Löschte Datenbanken sind ausgeschlossen.",
