  "Maîtrise automatique · après un intervalle de plus de (jours)": "Automatische Beherrschung · nach einem Intervall von mehr als (Tage)",
  "S’applique à toutes les bases, y compris aux cartes déjà au-delà de ce seuil : elles deviennent immédiatement maîtrisées et ne reviennent plus en révision. Les cartes déjà maîtrisées restent inchangées.": "Sie gilt für alle Datenbanken, auch für Karten, die diese Schwelle bereits überschritten haben: Sie werden sofort beherrscht und kehren nicht mehr zur Überprüfung zurück. Die bereits beherrschten Karten bleiben unverändert.",
