  "Chaque base conserve ensuite ses propres réglages. Modifier ces valeurs ne change pas les bases existantes.": "Jede Datenbank behält dann ihre eigenen Einstellungen. Die Änderung dieser Werte ändert keine bestehenden Datenbanken.",
