  "Progression des intervalles": "Intervallwachstum",
  "Pour une carte déjà vue, le délai précédent est multiplié selon ta réponse, puis limité par les minimums et le maximum de sa base. Manqué repart du délai court réglé dans la base.": "Für eine zuvor gezeigte Karte wird das vorherige Intervall entsprechend Ihrer Antwort multipliziert und dann durch die Mindest- und Höchstintervalle der Datenbank begrenzt. Wieder neu gestartet aus dem kurzen Intervall der Datenbank.",
