  "Le budget est partagé entre les imports et les deux moteurs : analyse interactive et tâches de fond. Les changements s’appliquent aux prochains calculs et aux prochains imports; un import déjà lancé conserve ses ressources.": "Der Haushalt wird zwischen den Einfuhren und zwei Schachmaschinen geteilt: Interaktive Analyse und Hintergrundarbeit. Änderungen gelten für zukünftige Berechnungen und Einfuhren; eine aktive Einfuhr behält ihre Ressourcen.",
