  "Les cartes au-delà de ce seuil deviennent maîtrisées. Leur historique est conservé et les rappels suivent les réglages d’entretien ci-dessous.": "Karten, die über diese Schwelle hinausgehen, werden beherrscht. Ihre Geschichte ist erhalten und die Erinnerungen folgen den unterstehenden Wartungseinstellungen.",
