  "Budget CPU (cœurs logiques)": "CPU-Budget (logische Kerne)",
  "Cache mémoire Stockfish total (Mo)": "Gesamter Stockfish-Speichercache (MB)",
  "Le cache mémoire est partagé entre les deux moteurs Stockfish. Ce réglage ne plafonne pas la RAM totale de ChessGym : Maia, les imports et l’interface utilisent aussi de la mémoire.": "Der Speichercache wird auf die beiden Stockfish-Engines verteilt. Diese Einstellung begrenzt nicht den gesamten Arbeitsspeicherverbrauch von ChessGym: Maia, Importe und die Benutzeroberfläche benötigen ebenfalls Speicher.",
  "Le budget CPU est partagé entre les calculs et les imports. Les tâches attendent si le budget est déjà utilisé. Les changements s’appliquent aux prochaines tâches.": "Das CPU-Budget wird zwischen Berechnungen und Importen geteilt. Ist es bereits ausgelastet, warten weitere Aufgaben. Änderungen gelten für die nächsten Aufgaben.",
  "La configuration enregistrée a été adaptée aux ressources de ce serveur.": "Die gespeicherte Konfiguration wurde an die Ressourcen dieses Servers angepasst.",
  "Choix : {cores} cœurs logiques, {memory} Mo de cache et {workers} processus d’importation.": "Auswahl: {cores} logische Kerne, {memory} MB Cache und {workers} Importprozesse.",
  "Avec ce petit budget CPU, certaines analyses et importations se déroulent l’une après l’autre.": "Bei diesem kleinen CPU-Budget werden manche Analysen und Importe nacheinander ausgeführt.",
  "Choisis un nombre de cœurs compris dans les limites de ce serveur.": "Wähle eine Anzahl an Kernen innerhalb der Grenzen dieses Servers.",
  "Choisis une quantité de mémoire cache comprise dans les limites de ce serveur.": "Wähle eine Cache-Größe innerhalb der Grenzen dieses Servers.",
  "Choisis un nombre de processus d’importation compris dans les limites de ce serveur.": "Wähle eine Anzahl an Importprozessen innerhalb der Grenzen dieses Servers.",
  "Le nombre de processus d’importation dépasse le budget CPU choisi.": "Die Anzahl der Importprozesse überschreitet das gewählte CPU-Budget.",
  "La durée doit être un nombre positif d’au moins 0,1 seconde.": "Die Dauer muss eine positive Zahl von mindestens 0,1 Sekunden sein.",
  "La profondeur doit être un entier positif accepté par le moteur.": "Die Tiefe muss eine positive ganze Zahl sein, die von der Engine unterstützt wird.",
  "La durée doit être un nombre entier de millisecondes positif.": "Die Dauer muss eine positive ganze Zahl in Millisekunden sein.",
  "Choisis le mode rapide ou une profondeur Stockfish entière positive.": "Wähle den Schnellmodus oder eine positive ganze Zahl als Stockfish-Tiefe.",
  "Choisis une profondeur entière positive, ou le mode rapide.": "Wähle eine positive ganze Zahl als Tiefe oder den Schnellmodus.",
  "La profondeur doit être un entier positif compatible avec le moteur.": "Die Tiefe muss eine positive ganze Zahl sein, die mit der Engine kompatibel ist.",
  "Le temps par position doit être un entier d’au moins 100 ms, représentable sans perte.": "Die Zeit pro Stellung muss eine ganze Zahl von mindestens 100 ms sein, die sich ohne Genauigkeitsverlust darstellen lässt.",
  "Choisis une durée ou une profondeur pour analyser la partie.": "Wähle eine Dauer oder eine Tiefe zur Analyse der Partie.",
  "Choisis une profondeur positive. Le calcul continue jusqu’à cette cible, sans limite de temps ajoutée. Une profondeur élevée peut demander longtemps ; tu peux arrêter les évaluations ou changer de position.": "Wähle eine positive Tiefe. Die Berechnung läuft bis zu diesem Ziel, ohne zusätzliches Zeitlimit. Eine hohe Tiefe kann lange dauern; du kannst die Bewertungen stoppen oder die Stellung wechseln.",
  "Choisis une profondeur entière positive compatible avec le moteur.": "Wähle eine positive ganze Zahl als Tiefe, die mit der Engine kompatibel ist.",
