  " non atteinte": " nicht erreicht",
  "Durée par position": "Zeit pro Stellung",
  "En mode profondeur, chaque position est analysée jusqu’à la cible, sans limite de temps ajoutée. En mode durée, le calcul utilise le temps choisi. Tu peux continuer à utiliser ChessGym ou annuler le bilan.": "Im Tiefenmodus wird jede Stellung bis zum Ziel analysiert, ohne zusätzliches Zeitlimit. Im Zeitmodus verwendet die Berechnung die gewählte Dauer. Du kannst ChessGym weiter nutzen oder den Bericht abbrechen.",
  "Choisis une durée d’au moins 0,1 seconde, avec au plus trois décimales.": "Wähle eine Dauer von mindestens 0,1 Sekunden mit höchstens drei Nachkommastellen.",
